import{EValidatorType}from"../enum/_enum.js";import{ErrorHandler}from"../libraries/errors/_errors.js";import{Wrapper}from"../utils/wrapper.js";const validator=options=>Wrapper((req,res,next)=>{try{const validate=schema=>{switch(schema.type){case EValidatorType.QueryParameter:req.query=schema.schema.parse(req.query);break;case EValidatorType.PathParameter:req.params=schema.schema.parse(req.params);break;case EValidatorType.RequestBody:req.body=schema.schema.parse(req.body);break}};if(Array.isArray(options)){for(const schema of options){validate(schema)}}else{validate(options)}}catch(error){throw new ErrorHandler({code:400,details:error.issues,message:"BAD_REQUEST"})}return next()});export{validator};